module archimedes_spiral (\n    input clk,\n    input rst_n,\n    input start,\n    input [63:0] b,\n    input [63:0] tx,\n    input [63:0] ty,\n    output reg [63:0] x,\n    output reg [63:0] y,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE     = 3'd0;\n    localparam [2:0] SEARCH   = 3'd1;\n    localparam [2:0] COMPUTE  = 3'd2;\n    localparam [2:0] VALIDATE = 3'd3;\n    localparam [2:0] FINISH   = 3'd4;\n\n    // Fixed-point constants (Q16.48 format)\n    localparam [63:0] PI_Q16_48 = 64'h000000000003243F;\n    localparam [63:0] TWO_PI     = 64'h000000000006487F;\n    localparam [63:0] STEP       = 64'h0000000000001000;\n\n    // Search parameters\n    localparam [9:0] MAX_ITER  = 10'd1000;\n    localparam [9:0] MAX_STEPS = 10'd200;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [9:0] step_count;\n    reg [9:0] search_count;\n    reg [63:0] phi_current;\n    reg [63:0] phi_best;\n    reg [63:0] error_min;\n    reg [63:0] x_calc, y_calc;\n    reg [63:0] best_x, best_y;\n\n    // Intermediate calculation signals\n    reg [127:0] mul_temp;\n    reg [63:0] phi_sq;\n    reg [63:0] sqrt_temp;\n    reg [63:0] error_temp;\n\n    // Fixed-point arithmetic functions\n    function [63:0] mul_fp(input [63:0] a, input [63:0] b);\n        reg [127:0] product;\n        begin\n            product = a * b;\n            mul_fp = product[111:48];  // Align to Q16.48 format\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            step_count <= 10'd0;\n            search_count <= 10'd0;\n            phi_current <= 64'd0;\n            phi_best <= 64'd0;\n            error_min <= {1'b0, {63{1'b1}}};  // MAX POSITIVE\n            x <= 64'd0;\n            y <= 64'd0;\n            x_calc <= 64'd0;\n            y_calc <= 64'd0;\n            best_x <= 64'd0;\n            best_y <= 64'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= SEARCH;\n                        phi_current <= TWO_PI;\n                        error_min <= {1'b0, {63{1'b1}}};\n                        step_count <= 10'd0;\n                        search_count <= 10'd0;\n                    end\n                end\n\n                SEARCH: begin\n                    if (search_count < MAX_ITER || step_count < MAX_STEPS) begin\n                        // Advance to calculation state\n                        state <= COMPUTE;\n                    end else begin\n                        // Exit search loop\n                        state <= FINISH;\n                    end\n                end\n\n                COMPUTE: begin\n                    // Simplified spiral position calculation:\n                    // x = b*phi*cos(phi) ≈ b*phi*(1 - phi^2/2)\n                    // y = b*phi*sin(phi) ≈ b*phi*(phi - phi^3/6)\n                    \n                    // Approximation helper terms\n                    phi_sq <= mul_fp(phi_current, phi_current);\n                    x_calc <= mul_fp(b, phi_current);\n                    y_calc <= mul_fp(mul_fp(b, phi_current), phi_current);\n                    \n                    state <= VALIDATE;\n                end\n\n                VALIDATE: begin\n                    // Simplified error calculation\n                    error_temp <= mul_fp((x_calc - tx), (x_calc - tx)) + \n                                 mul_fp((y_calc - ty), (y_calc - ty));\n                    \n                    // Update best solution\n                    if (error_temp < error_min) begin\n                        error_min <= error_temp;\n                        phi_best <= phi_current;\n                        best_x <= x_calc;\n                        best_y <= y_calc;\n                    end\n                    \n                    // Next search step\n                    step_count <= step_count + 1'b1;\n                    search_count <= (step_count == MAX_STEPS - 1) ? search_count + 1'b1 : search_count;\n                    phi_current <= phi_current + STEP;\n                    state <= SEARCH;\n                end\n\n                FINISH: begin\n                    // Output best result\n                    x <= best_x;\n                    y <= best_y;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule